const clubTrophyIcon='<svg viewBox="0 0 80 100" fill="none" stroke="currentColor" stroke-width="3" aria-hidden="true"><path d="M23 10h34v26a17 17 0 0 1-34 0V10Zm0 7H10v15a18 18 0 0 0 17 18m30-33h13v15a18 18 0 0 1-17 18M40 54v25M25 90h30l-5-11H30z"/><path d="M29 17h22v18a11 11 0 0 1-22 0z" fill="currentColor" opacity=".2"/></svg>';const clubHonoursView=()=>{const titles=[['23/24','AFC Cup Participant','participation'],['18/19','Promoted to 1st league','promotion'],['09/10','Promoted to 1st league','promotion'],['00/01','Promoted to 1st league','promotion'],['1996','Malaysian Champions','trophy'],['94/95','Malaysian FA Cup Winner','trophy']];return '<section class="club-honours-page"><header class="club-honours-hero">'+clubLogo('Sabah FC','honours-club-crest')+'<div><span>SABAH FC · CLUB HISTORY</span><h2 class="club-honours-heading">Honours List</h2><p>Sejarah kejayaan dan pencapaian Sabah FC.</p></div></header><div class="club-honours-layout"><section class="club-victories"><h2>Info</h2><p class="club-victories-label">Victories page</p><div class="club-trophy-grid">'+[['Malaysian Champions','1996','champions'],['Malaysian FA Cup Winner','94/95','fa-cup']].map(([title,year,file])=>'<article class="club-trophy-card"><h3><span>1×</span> '+title+'</h3><div class="club-trophy-body"><div class="club-trophy-art"><img src="assets/trophies/'+file+'.webp" alt="Piala '+title+'" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span hidden>'+clubTrophyIcon+'</span></div><strong>'+year+'</strong></div></article>').join('')+'</div></section><section class="club-all-titles"><h2>All Titles</h2><table><thead><tr><th scope="col">Season</th><th scope="col">Title</th></tr></thead><tbody>'+titles.map(([season,title,type])=>'<tr><td>'+season+'</td><td><span class="club-title-icon '+type+'" aria-hidden="true">'+(type==='promotion'?'↑':clubTrophyIcon)+'</span><span>'+title+'</span></td></tr>').join('')+'</tbody></table></section></div><p class="match-disclaimer">Rekod berdasarkan maklumat rujukan yang dibekalkan.</p></section>'};
function view(){if(page==='match-edit')return matchEditor();if(page==='player-edit')return squadEdit();if(page==='player-profile')return squadProfile();if(page==='detail')return matchDetail();function homeCalendar(){const y=calendarMonth.getFullYear(),mo=calendarMonth.getMonth(),first=new Date(y,mo,1).getDay(),days=new Date(y,mo+1,0).getDate(),matches=allMatches().filter(m=>m.date);const monthName=calendarMonth.toLocaleDateString('en-GB',{month:'long',year:'numeric'});const cells=[];for(let i=0;i<first;i++)cells.push('<span class="cal-blank" aria-hidden="true"></span>');for(let day=1;day<=days;day++){const date=y+'-'+String(mo+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');const games=matches.filter(m=>m.date===date);cells.push('<button type="button" class="cal-day '+(games.length?'has-game ':'')+(date===malaysiaToday()?'cal-today':'')+'" '+(games.length?'data-calendar-match="'+matchIndex(games[0])+'"':'disabled')+' aria-label="'+date+(games.length?' match '+games.map(m=>m.home+' versus '+m.away).join(', '):'')+'">'+(games.length?'<span class="cal-badges">'+games.map(m=>clubLogo(m.home==='Sabah FC'?m.away:m.home,'cal-crest '+(competitionOf(m)==='fa'?'cal-crest--fa':'cal-crest--msl'))).join('')+'</span>':'<span class="cal-date">'+day+'</span>')+'</button>')}return '<section class="home-calendar" aria-label="Match calendar"><div class="home-calendar-head"><div><span class="portal-eyebrow">SABAH FC · 2026/27</span><h2>Match Calendar</h2><p>Semua pertandingan · Tekan logo untuk butiran perlawanan.</p></div><div class="cal-controls"><button type="button" data-cal-step="-1" aria-label="Previous month">‹</button><strong>'+monthName+'</strong><button type="button" data-cal-step="1" aria-label="Next month">›</button></div></div><div class="cal-weekdays">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="cal-grid">'+cells.join('')+'</div><div class="cal-competition-key" aria-label="Calendar competition colours"><span><i class="cal-key-msl"></i>MSL</span><span><i class="cal-key-fa"></i>FA Cup</span></div></section>'}if(page==='home'){const all=allMatches().filter(m=>competitionOf(m)===homeCompetition).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));const today=malaysiaToday();const previous=all.filter(m=>m.status==='FULL TIME').slice(-1);const next=all.filter(m=>m.status!=='FULL TIME'&&m.status!=='POSTPONED'&&(m.date||'')>=today).slice(0,2);const selected=[...previous,...next];for(const m of [...all].reverse())if(selected.length<3&&!selected.includes(m))selected.push(m);const shown=(selected.length?selected:all.slice(-3)).slice(0,3);const card=m=>{const finished=m.status==='FULL TIME',live=m.status==='LIVE';const score=finished||live?esc(m.homeScore)+' - '+esc(m.awayScore):esc(m.time||'--:--');const status=finished?'FULL TIME':live?'LIVE':m.status==='POSTPONED'?'POSTPONED':'PREVIEW';return '<div class="schedule-day">'+formatDate(m.date)+'</div><article class="schedule-card" role="button" tabindex="0" data-open-match="'+matchIndex(m)+'"><div class="schedule-competition">'+esc(homeCompetition==='fa'?'MALAYSIA FA CUP 2026':'MALAYSIA SUPER LEAGUE 2026/2027')+'</div><div class="schedule-match"><div class="schedule-club">'+clubLogo(m.home,'schedule-crest')+'<strong>'+esc(m.home)+'</strong></div><div class="schedule-middle"><span class="schedule-status '+(live?'live':'')+'">'+status+'</span><div class="schedule-score">'+score+'</div><span class="schedule-small">'+(finished?esc(matchRoundLabel(m)):esc(m.time?'MYT':'TIME TBA'))+'</span></div><div class="schedule-club">'+clubLogo(m.away,'schedule-crest')+'<strong>'+esc(m.away)+'</strong></div></div><div class="schedule-ground">'+esc(m.venue||'Venue TBA')+'</div>'+editAction(m)+'</article>'};return '<section class="club-home"><div class="schedule-title"><div><span>CLUB MATCH CENTRE</span><h2>Schedules</h2></div><button data-go="matches">View all →</button></div><div class="home-competition-tabs">'+[['league','Super League'],['fa','FA Cup']].map(([id,label])=>'<button data-home-competition="'+id+'" class="'+(homeCompetition===id?'active':'')+'">'+label+'</button>').join('')+'</div><div class="schedule-list">'+(shown.length?shown.map(card).join(''):'<div class="schedule-empty">Belum ada jadual disahkan untuk pertandingan ini.</div>')+'</div><p class="match-disclaimer">Jadual dan keputusan mungkin berubah. Portal tidak rasmi; bukan suapan data langsung.</p></section>'+homeCalendar()};if(page==='matches')return '<section class="match-centre"><div class="competition-tabs">'+competitions.map(([id,name])=>'<button class="competition-tab '+(competition===id?'active':'')+'" data-competition="'+id+'">'+esc(id==='fa'?'FA Cup':'Super League')+'</button>').join('')+'</div><div class="competition-caption">'+esc(competitions.find(x=>x[0]===competition)[1])+'</div><div class="match-toolbar"><div class="match-filters"><button data-match-filter="all" class="'+(matchFilter==='all'?'active':'')+'">All</button><button data-match-filter="fixtures" class="'+(matchFilter==='fixtures'?'active':'')+'">Fixtures</button><button data-match-filter="results" class="'+(matchFilter==='results'?'active':'')+'">Results</button></div><span class="match-count">'+visibleMatches().length+' matches</span></div><div class="fixture-list">'+matchRows()+'</div><p class="match-disclaimer">Maklumat tertakluk kepada perubahan penganjur. Data ini bukan kemas kini langsung.</p></section>';if(page==='players')return squadView();if(page==='standing'){const snapshot=[["Johor Darul Ta'zim",6,6,0,0,18,28,0,"WWWWW"],["Selangor FC",6,6,0,0,18,17,4,"WWWWW"],["Kuching City FC",6,4,0,2,12,17,7,"WWWWL"],["DPMM FC",6,4,0,2,12,9,8,"LLWWW"],["Sabah FC",6,3,1,2,10,9,6,"WLLDW"],["Melaka FC",6,3,0,3,9,10,12,"WLLWW"],["Kuala Lumpur City FC",6,2,0,4,6,6,16,"LWWLL"],["Negeri Sembilan FC",6,1,2,3,5,8,11,"LDLDL"],["Terengganu FC",6,1,2,3,5,4,9,"LDDLL"],["Star City FC",6,1,2,3,5,9,16,"LDDWL"],["Penang FC",6,1,1,4,4,5,10,"LDWLL"],["Kelantan Red Warrior FC",6,0,0,6,0,6,29,"LLLLL"]];const official='https://www.malaysianfootballleague.com/Home/Sport?&WHurl=%2Fstandings%3F';return '<section class="panel standing-panel"><div class="standing-head"><div><span class="portal-eyebrow">MALAYSIA SUPER LEAGUE · 2026/27</span><h2>League Table</h2><p class="muted">12 Clubs · Matchday 6 · MFL reference</p></div><a class="standing-official-link" href="'+official+'" target="_blank" rel="noopener noreferrer">Official MFL Standings ↗</a></div><div class="standing-table-scroll" role="region" aria-label="Super League standings" tabindex="0"><table class="standing-table"><thead><tr><th scope="col">#</th><th scope="col">Club</th><th scope="col">MP</th><th scope="col">W</th><th scope="col">D</th><th scope="col">L</th><th scope="col">GF</th><th scope="col">GA</th><th scope="col">GD</th><th scope="col">Pts</th><th scope="col">Last 5</th></tr></thead><tbody>'+snapshot.map((t,i)=>'<tr'+(t[0]==='Sabah FC'?' class="sabah-highlight"':'')+'><td>'+(i+1)+'</td><td><div class="standing-club">'+clubLogo(t[0],'standing-crest')+'<strong>'+esc(t[0])+'</strong></div></td><td>'+t[1]+'</td><td>'+t[2]+'</td><td>'+t[3]+'</td><td>'+t[4]+'</td><td>'+t[6]+'</td><td>'+t[7]+'</td><td>'+(t[6]-t[7]>0?'+':'')+(t[6]-t[7])+'</td><td class="standing-points"><strong>'+t[5]+'</strong></td><td><div class="standing-form" aria-label="Last 5: '+t[8]+'">'+t[8].split('').map(f=>'<span class="standing-form-dot form-'+f.toLowerCase()+'" title="'+(f==='W'?'Win':f==='D'?'Draw':'Loss')+'">'+(f==='W'?'✓':f==='D'?'−':'×')+'</span>').join('')+'</div></td></tr>').join('')+'</tbody></table></div><p class="muted standing-legend">MP: Matches Played · W: Wins · D: Draws · L: Losses · GF: Goals For · GA: Goals Against · GD: Goal Difference · Pts: Points · Last 5: W menang, D seri, L kalah (kiri ke kanan mengikut data yang diberikan)</p></section>'};if(page==='stats')return squadStatsView();if(page==='about')return '<div class="panel"><h2>About Sabah FC Fan Portal</h2><p>'+esc(data.about)+'</p><p class="notice">Tidak berafiliasi secara rasmi dengan Sabah FC atau Malaysia Football League. Data disediakan untuk demonstrasi dan perlu disahkan sebelum penerbitan.</p></div>'+clubHonoursView();return '<div class="panel"><h2>Admin · Editor Demo</h2><div class="actions"><button type="button" class="primary" data-toggle-admin>Mod Admin: '+(adminMode?'ON':'OFF')+'</button><button type="button" class="secondary" data-new-match>+ Tambah Perlawanan</button></div><h3>Opponent Teams</h3><p class="muted">Senarai pasukan yang tersedia untuk pilihan Home / Away.</p><div class="opponent-grid">'+[...new Set([...Object.keys(clubLogoUrls),...(data.opponents||[])])].filter(n=>n!=='Sabah FC').sort().map(n=>'<div class="opponent-item">'+clubLogo(n,'opponent-crest')+'<span>'+esc(n)+'</span></div>').join('')+'</div><form id="opponentForm" class="form"><label class="wide">Tambah nama pasukan lawan<input name="opponent" required maxlength="100" placeholder="Nama kelab"></label><button class="primary">Tambah Pasukan</button></form><h3>Manage Fixtures</h3><div class="admin-fixture-list">'+allMatches().map(m=>'<div class="admin-fixture-item"><span>'+formatDate(m.date)+' · '+esc(m.home)+' vs '+esc(m.away)+'</span>'+'<button type="button" class="match-edit-btn admin-always" data-edit-match="'+matchIndex(m)+'">✎ Edit</button>'+'</div>').join('')+'</div><p class="notice">Editor ini menyimpan data hanya pada pelayar peranti ini (localStorage). Tiada login selamat atau penyelarasan cloud. Jangan masukkan maklumat sulit.</p><h2>Tambah Pemain</h2><form id="playerForm" class="form"><label>Nama<input name="name" required maxlength="80"></label><label>No. Jersi<input name="number" type="number" min="0" max="99"></label><label>Posisi<select name="position"><option>GK</option><option>DF</option><option>MF</option><option>FW</option></select></label><label>Negara<input name="nationality" value="Malaysia"></label><p class="wide profile-note">Gol, assist dan kad dikira secara automatik daripada rekod Matches untuk setiap pertandingan.</p><div class="wide"><button class="primary">Simpan Pemain</button></div></form><hr><h2>Tambah Perlawanan</h2><form id="matchForm" class="form"><label class="wide">Pertandingan<select name="competition"><option value="league">Malaysia Super League 2026/2027</option><option value="fa">Malaysia FA Cup 2026</option></select></label><label>Home<input name="home" value="Sabah FC" required></label><label>Away<input name="away" required></label><label>Tarikh<input name="date" type="date"></label><label>Masa MYT<input name="time" type="time"></label><label>Stadium<input name="venue"></label><label>Status<select name="status"><option>PREVIEW</option><option>LIVE</option><option>FULL TIME</option><option>POSTPONED</option></select></label><label>Gol Home<input name="homeScore" type="number" min="0" value="0"></label><label>Gol Away<input name="awayScore" type="number" min="0" value="0"></label><div class="wide"><button class="primary">Simpan Perlawanan</button></div></form><hr><div class="actions"><button id="export" class="secondary">Export JSON</button><button id="clear" class="secondary">Reset Data Tempatan</button></div></div>'}function publishStatusMarkup(){return adminMode?'<aside class="publish-status" aria-label="Status penerbitan admin"><p id="publishStatusMessage" role="status" data-state="'+publishState+'">'+esc(publishMessage)+'</p><div>'+(isGitHubPages?'<a href="https://sabah-fc.pages.dev" target="_blank" rel="noopener noreferrer">Buka laman Cloudflare</a>':'<a href="/api/admin/session?login=1" target="_blank" rel="noopener noreferrer">Log masuk penerbitan</a><button type="button" data-publish-now>Terbit sekarang</button>')+''+((readLocalJson(RECOVERY_KEY)||[]).length?'<button type="button" data-export-local-backup>Export draf lama</button>':'')+'</div></aside>':''}function updatePublishStatus(message,state){publishMessage=message;publishState=state;const element=document.getElementById('publishStatusMessage');if(element){element.textContent=message;element.dataset.state=state}document.querySelectorAll('[data-publish-now]').forEach(button=>button.disabled=publishBusy)}function schedulePublish(){if(!adminMode)return;if(isGitHubPages){updatePublishStatus('Disimpan dalam pelayar ini. GitHub Pages tidak menyokong auto-publish; eksport data untuk penerbitan, atau gunakan editor Cloudflare yang telah dikonfigurasi.','local');return}clearTimeout(publishTimer);updatePublishStatus('Disimpan dalam pelayar. Menunggu penerbitan automatik…','pending');publishTimer=setTimeout(publishAll,900)}async function publishAll(){if(!adminMode)return;if(isGitHubPages){schedulePublish();return}if(publishBusy){publishPending=true;return}clearTimeout(publishTimer);if(!publishedRevision){updatePublishStatus('Data penerbitan belum dimuatkan. Eksport salinan tempatan dan muat semula sebelum menerbitkan.','error');return}publishBusy=true;let succeeded=false;updatePublishStatus('Menyimpan maklumat ke GitHub…','pending');try{const response=await fetch('/api/admin/publish',{method:'POST',credentials:'same-origin',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRevision:publishedRevision,data:{...data,playerProfiles}})});const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('Log masuk penerbitan diperlukan. Data masih disimpan dalam pelayar.');const result=await response.json();if(!response.ok)throw new Error(result.error||'Penerbitan gagal. Data masih disimpan dalam pelayar.');if(!result.published||typeof result.revision!=='string')throw new Error('Status penerbitan tidak dapat disahkan.');markPublishedRevision(result.revision);succeeded=true;updatePublishStatus(result.unchanged?'Data sudah sama dengan GitHub.':('Berjaya dihantar ke GitHub ('+String(result.commit||'').slice(0,7)+'). Tunggu deploy Cloudflare selesai.'),'success')}catch(error){updatePublishStatus(error instanceof TypeError?'Penerbitan belum tersedia. Log masuk penerbitan atau semak konfigurasi Cloudflare; data tempatan masih disimpan.':error.message,'error')}finally{publishBusy=false;document.querySelectorAll('[data-publish-now]').forEach(button=>button.disabled=false);if(publishPending){publishPending=false;if(succeeded)publishAll()}}}
function editorOpen(){return page==='match-edit'||page==='player-edit'||page==='admin'}function applyPublishedData(snapshot){const previousMatch=page==='detail'?allMatches()[selectedMatch]:null;const fresh=selectPortalData({published:snapshot,admin:false,fallback:seed});for(const key of ['players','matches','teams','about','opponents'])if(snapshot[key]!==undefined)seed[key]=snapshot[key];data={...structuredClone(seed),...fresh.data};playerProfiles=fresh.profiles;publishedData=snapshot;publishedRevision=snapshot.revision;awaitingDeployment=null;queuedPublishedData=null;localSaveNotice='Data terkini telah dimuatkan.';if(previousMatch)selectedMatch=allMatches().findIndex(m=>previousMatch.refIndex!=null?m.refIndex===previousMatch.refIndex:m.home===previousMatch.home&&m.away===previousMatch.away&&m.date===previousMatch.date)}async function refreshPublishedData(){if(syncBusy||document.hidden||publishBusy)return;syncBusy=true;try{const snapshot=await fetchPublishedData();if(!snapshot)return;if(snapshot.revision===publishedRevision){if(awaitingDeployment){publishedData=snapshot;awaitingDeployment=null;for(const key of ['players','matches','teams','about','opponents'])if(snapshot[key]!==undefined)seed[key]=snapshot[key]}return}if(awaitingDeployment&&snapshot.revision===awaitingDeployment.previousRevision)return;if(hasPendingDraft){queuedPublishedData=snapshot;updatePublishStatus('Data baharu telah diterbitkan pada peranti lain. Eksport draf tempatan sebelum memuat semula; draf anda tidak dipadam.','error');return}if(editorOpen()){queuedPublishedData=snapshot;return}applyPublishedData(snapshot);const scrollPosition=window.scrollY;render();window.scrollTo(0,scrollPosition)}finally{syncBusy=false}}
